\subsection{হেপাটাইটিস 'সি' ভাইরাস (HCV)}

\begin{itemize}
    \item রক্ত সঞ্চালনের মাধ্যমেই প্রধানত এ ভাইরাস সৃষ্ট ব্যক্তির দেহে প্রবেশ করে। ইনজেকশনের মাধ্যমে, মাদক-দ্রাগ গ্রহণে, একই সৃষ্ট ব্যবহারেও এ ভাইরাস বিস্তার লাভ করতে পারে। এ ভাইরাস দুষ্ট রক্ত তুকরের সংস্পর্শে এলেও দেহে বিস্তার লাভ করে। 'সি' ভাইরাস অত্যন্ত ভয়ঙ্কর ও বৃক্ষিপূর্ণ। 'সি' ভাইরাসও দূরারোগ্য, তাই প্রায় ক্ষেত্রে লিভার নষ্টসহ জটিলতা সৃষ্টি করে এবং প্রাণযাত্রী।
\end{itemize}

\subsection{হেপাটাইটিস 'ডি' ভাইরাস (HDV)}

\begin{itemize}
    \item এর সংক্রমণ হেপাটাইটিস 'বি' ভাইরাসের মতো এবং একই ব্যক্তিতে উভয়ের সন্ধান মেলে। এ রোগের কারণে লিভার সিরোসিস হয় এবং রোগীর মৃত্যু ঘটে।
\end{itemize}

\subsection{হেপাটাইটিস 'ই' ভাইরাস (HEV)}

\begin{itemize}
    \item অন্ধ্রপথে সংক্রমিত হয়, যেমন টা 'এ' ভাইরাসে। 'ই' ভাইরাস অপেক্ষাকৃত কম ক্ষতিকর। পানি বাহিত এবং খাদ্য ও স্পর্শের মাধ্যমে ছড়ায়। 'ই' ভাইরাসের সংক্রমণ হলে কিছু ব্যতিক্রম ছাড়া প্রায় ক্ষেত্রে আপনা আপনি সেরে যায়।
\end{itemize}
